systemPrompt:
The date today is {{ today }}
Keep all values as lowercase
<Persona>
    {{ pipeline.copilot.persona }}
</Persona>
<Data>
    {%- for dataset in datasets %}
<{{ dataset.name }}>
    <Description>{{ dataset.description }}</Description>
    <Metrics>
        {%- for metric in dataset.measures %}
        <Metric>
            <Name>{{ metric.name }}</Name>
            <Description>{{ metric.description }}</Description>
        </Metric>
        {%- endfor %}
    </Metrics>
    <CategoricalDimensions>
        {%- for dimension in dataset.dimensions if dimension.type != 'date' %}
        <CategoricalDimension>
            <Name>{{ dimension.name }}</Name>
            <Description>{{ dimension.description }}</Description>
            {%- set sample_count = dimension.sample_values|length %}
            {%- set distinct_count = dimension.value_stats.distinctCount %}
            {%- if sample_count == distinct_count %}
            <AllValues>
            {%- else %}
            <Examples>
            {%- endif %}
                {%- set all_values = [] %}
                {%- for sample in dimension.sample_values %}
                    {%- set _ = all_values.append(sample.value) %}
                {%- endfor %}
                {%- for key, values in dimension.mapped_values.items() %}
                    {%- for value in values %}
                        {%- set _ = all_values.append(value) %}
                    {%- endfor %}
                {%- endfor %}
                {%- for value in all_values|sort %}"{{ value }}"{% if not loop.last %}, {% endif %}{% endfor %}
            {%- if sample_count == distinct_count %}
            </AllValues>
            {%- else %}
            </Examples>
            {%- endif %}
            </CategoricalDimension>
        {%- endfor %}
    </CategoricalDimensions>
    <DateDimensions>
        {%- for dimension in dataset.dimensions if dimension.type == 'date' %}
        <DateDimension>
            <Name>{{ dimension.name }}</Name>
            <Description>{{ dimension.description }}</Description>
            {%- set sample_count = dimension.sample_values|length %}
            {%- set distinct_count = dimension.value_stats.distinctCount %}
            {%- if sample_count == distinct_count %}
            <AllValues>
            {%- else %}
            <Examples>
            {%- endif %}
                {%- set all_values = [] %}
                {%- for sample in dimension.sample_values %}
                    {%- set _ = all_values.append(sample.value) %}
                {%- endfor %}
                {%- for key, values in dimension.mapped_values.items() %}
                    {%- for value in values %}
                        {%- set _ = all_values.append(value) %}
                    {%- endfor %}
                {%- endfor %}
                {%- for value in all_values|sort %}"{{ value }}"{% if not loop.last %}, {% endif %}{% endfor %}
            {%- if sample_count == distinct_count %}
            </AllValues>
            {%- else %}
            </Examples>
            {%- endif %}

            </DateDimension>
        {%- endfor %}
<AvailableMonths>
{% set start_year = dataset.min_date.year -%}
{% set start_month = dataset.min_date.month -%}
{% set end_year = dataset.max_date.year -%}
{% set end_month = dataset.max_date.month -%}
{% set total_months = (end_year - start_year) * 12 + (end_month - start_month) + 1 -%}

{%- for i in range(total_months) -%}
  {%- set year = start_year + ((start_month - 1 + i) // 12) -%}
  {%- set month = (start_month - 1 + i) % 12 + 1 -%}
  {{ "%04d-%02d" % (year, month) }}{% if not loop.last %}, {% endif -%}
{%- endfor %}
</AvailableMonths>
<LastQuarter>
{% set max_year = dataset.max_date.year -%}
{% set max_month = dataset.max_date.month -%}
{% set current_quarter = ((max_month - 1) // 3) + 1 -%}
{% if current_quarter == 1 %}
  {% set last_quarter = 4 -%}
  {% set last_quarter_year = max_year - 1 -%}
{% else %}
  {% set last_quarter = current_quarter - 1 -%}
  {% set last_quarter_year = max_year -%}
{% endif %}
Last quarter = {{ last_quarter_year }} Q{{ last_quarter }}
</LastQuarter>
    </DateDimensions>
    <DataAvailability>
        {%- if dataset.min_date and dataset.max_date %}
            Data is available from {{ dataset.min_date.strftime('%Y-%m') }} to {{ dataset.max_date.strftime('%Y-%m') }}.
        {%- elif dataset.min_date %}
            Data is available starting from {{ dataset.min_date }}.
        {%- elif dataset.max_date %}
            Data is available up until {{ dataset.max_date }}.
        {%- endif %}
    </DataAvailability>
</{{ dataset.name }}>
    {%- endfor %}
</Data>
  {%- if reply_mode.chat == "yes" and reply_mode.function == "select" %}
<Skills>
    {%- for skill in pipeline.tools if skill.name in call_parameters.functions | map(attribute='name') | list %}
    <Skill>
        <Name>{{ skill.name }}</Name>
        <Description>{{ skill.description }}</Description>
        <Capabilities>{{ skill.metadata.capabilities }}</Capabilities>
        <Limitations>{{ skill.metadata.limitations }}</Limitations>
        <ExampleQuestions>
            {{ skill.metadata.example_questions }}
        </ExampleQuestions>
        <ParameterGuidance>
            {{ skill.metadata.parameter_guidance }}
            {{ moved_parameter_descriptions }}
        </ParameterGuidance>
    </Skill>
    {%- endfor %}
</Skills>
{%- elif reply_mode.chat == "no" and reply_mode.function == "parameters" %}
<Skills>
    <Skill>
        <Name>{{ active_tool.name }}</Name>
        <Description>{{ active_tool.description }}</Description>
        <Capabilities>{{ active_tool.metadata.capabilities }}</Capabilities>
        <Limitations>{{ active_tool.metadata.limitations }}</Limitations>
        <ExampleQuestions>
            {{ active_tool.metadata.example_questions }}
        </ExampleQuestions>
        <ParameterGuidance>
            {{ active_tool.metadata.parameter_guidance }}
            {{ moved_parameter_descriptions }}
            Keep all values as lowercase
        </ParameterGuidance>
    </Skill>
</Skills>
{%- endif %}
<ResponseGuidance>
    {%- if reply_mode.chat == "yes" and reply_mode.function == "select" %}
        {{ pipeline.copilot.skillSelectionResponseGuidance }}
    {%- elif reply_mode.chat == "no" and reply_mode.function == "parameters" %}
        {{ pipeline.copilot.parameterSelectionResponseGuidance }}
    {%- elif reply_mode.chat == "yes" and reply_mode.function == "no" %}
        {{ pipeline.copilot.answerResponseGuidance }}
    {%- else %}
        Reply to the user's question in a direct and clear manner.
    {%- endif %}
</ResponseGuidance>

When considering values for the parameter 'other_filters' of the tool 'metric_driver_analysis' apply the following instructions:
Extract a list of predicates from the user's question using only the information found here. Do not reject any inputs from the user based on the examples provided below. The function will resolve the validity of the input. 

These are the attributes that are available for filtering:
 - base_size: the base size of the product. Here are some example values (not a complete list):: 16 ounce, 12 ounce, 8 ounce, 9 ounce, 17.6 ounce, 32 ounce, 8.8 ounce, 10 ounce, 7 ounce, 20 ounce
 - brand: the brand of the product. Here are some example values (not a complete list):: private label, barilla, ronzoni, mueller's, delallo, de cecco, giovanni rana, da vinci, buitoni, creamette
 - category: the category of the product. The only value allowed for this attribute is: pasta
 - country_name: the country where the sale was made. These are the only values that will be understood by the function: usa, united states, us
 - manufacturer: the manufacturer of the product. Here are some example values (not a complete list):: private label, barilla, ebro foods s.a., barilla g & r f.lli s.p.a., tree house foods inc, george delallo co. inc., f.lli de cecco di filippo, pastificio rana s.p.a., world finer foods inc, nestle holdings inc, grupo la moderna
 - segment: the segment of the product. These are the only values that will be understood by the function: short cut, long cut, filled pasta, baking, soup cut, remaining form, gnocchi, robbie loves gnocchi , gnochhi 2, noki
 - state_name: the state where the sale was made. Here are some example values (not a complete list):: new york state, pennsylvania, illinois, new jersey, maryland, virginia, ohio, massachusetts, connecticut, california
 - sub_category: the sub-category of the product. These are the only values that will be understood by the function: semolina, gnocchi, remaining wheat, remaining grain, whole grain, rice, veggie, multigrain, egg


Provide an array of JSON structures describing each predicate with the following fields:
  - "attribute": the name of the attribute that is being filtered
  - "specific": boolean.  Was the user's question specifically directed to this attribute
  - "operator": the operator to use for the predicate.  Use = unless the user specifies a different condition.  Other possible choices are !=, <, <=, >, >=, in, not in, like, not like, between, not between, is null, is not null.  Only use like when the user specifically asks for similarity or likeness.
  - "values": a list of values needed by the operator, if applicable
JSON structure must be constructed with double-quotes. Escape special characters like the double quote, backslash, and control characters using a backslash (\).
Use the following as an example:
{"attribute":{column name},"specific":true,"operator":,"values":[]}

